-- The to-do tab kept its reminders in component state, seeded with sample
-- rows, so nothing a user added survived a reload. These two tables are where
-- they live now.
--
-- ids are generated by the client (gen_random_uuid() is only the fallback):
-- the tab adds a reminder to the list the moment you file it, and a
-- client-made id means that optimistic row is already the real one.

create table public.reminder_categories (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.users (id) on delete cascade,
  name       text not null check (length(btrim(name)) between 1 and 24),
  -- a single emoji, picked freehand
  icon       text not null default '' check (length(icon) <= 16),
  created_at timestamptz not null default now()
);

create index ix_reminder_categories_user on public.reminder_categories (user_id);

create table public.reminders (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.users (id) on delete cascade,
  title      text not null check (length(btrim(title)) between 1 and 200),
  kind       text not null,
  done       boolean not null default false,
  -- local dates from the client, like habit_entries.entry_date
  start_date date,
  end_date   date,
  at_time    time,
  place      text not null default '' check (length(place) <= 120),
  -- either one of the app's built-in categories (a slug like 'work') or the
  -- id of a row in reminder_categories — hence text and no foreign key
  category_id text check (length(category_id) <= 40),
  created_at timestamptz not null default now(),

  constraint ck_reminder_kind check (kind in ('refile', 'backlog', 'floater', 'anchor')),
  -- refile/backlog are undated; a floater is a window; an anchor is one day
  constraint ck_reminder_dates check (
    (kind in ('refile', 'backlog')
       and start_date is null and end_date is null and at_time is null) or
    (kind = 'floater'
       and start_date is not null and end_date is not null
       and end_date >= start_date and at_time is null) or
    (kind = 'anchor' and start_date is not null and end_date is null)
  )
);

create index ix_reminders_user on public.reminders (user_id);

alter table public.reminder_categories enable row level security;
alter table public.reminders           enable row level security;

create policy reminder_categories_own_rows on public.reminder_categories
for all
using (user_id = auth.uid())
with check (user_id = auth.uid());

create policy reminders_own_rows on public.reminders
for all
using (user_id = auth.uid())
with check (user_id = auth.uid());

grant select, insert, update, delete on public.reminder_categories to authenticated;
grant select, insert, update, delete on public.reminders to authenticated;
